const STORAGE='arquivo-morto-visitante-01';
const defaults={found:{},notes:[],bookmarks:[],settings:{motion:true,sound:false},proxy:{name:'',archetype:'Perseguidor',pilar:'Ruído',vigor:2,det:2,agilidade:2,forca:2,astucia:2,pericia:2,stress:0},visits:0};
let state;try{state=Object.assign({},defaults,JSON.parse(localStorage.getItem(STORAGE)||'{}'));}catch(e){state=JSON.parse(JSON.stringify(defaults));}
state.found=state.found||{};state.notes=state.notes||[];state.bookmarks=state.bookmarks||[];state.settings={...defaults.settings,...(state.settings||{})};state.proxy={...defaults.proxy,...(state.proxy||{})};state.visits=(state.visits||0)+1;
const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch(e){}};save();
