const topics=[
{id:'0033',cat:'fenomenos',title:'A TV liga sozinha às 03:33',author:'fita_07',date:'17/06/2003, 23:41',replies:6,desc:'Estranho problema com televisor e gravação.',posts:[{by:'fita_07',time:'17/06/2003, 23:41',txt:'Alguém mais teve esse problema? Minha televisão está ligando sozinha no mesmo horário há quatro noites. Não importa se tiro da tomada.\n\nGravei uma fita ontem. Alguém consegue me ajudar a descobrir o que aconteceu?\n\nDeixei o arquivo anexo. Ele pede uma senha que o gerente da locadora usava. A dica é aquela coisa que a gente tinha que fazer com a fita antes de devolver.' ,attach:'anexo_locadora_07.zip'},{by:'analogkid',time:'18/06/2003, 00:10',txt:'Não joga fora a fita. Essas gravações antigas somem rápido. E verifica o relógio do vídeo, não o do aparelho.'},{by:'mestre_antigo',time:'18/06/2003, 01:02',txt:'Se não conseguir assistir, anote o número que aparecer na etiqueta do verso. Às vezes o anexo é só uma referência.'}]},
{id:'0042',cat:'arquivos',title:'[TÓPICO REMOVIDO] índice de backups',author:'admin_000',date:'--/--/----',replies:0,desc:'Acesso ao histórico não autorizado.',posts:[{by:'admin_000',time:'[data ilegível]',txt:'O conteúdo deste tópico foi removido pelo moderador.\n\n[ Esta página está disponível apenas como cópia. ]'}]},
{id:'0097',cat:'tecnologia',title:'Videocassete Philips: como rebobinar sem controle?',author:'analogkid',date:'14/04/2002, 14:34',replies:12,desc:'Conversa técnica e fita presa no cabeçote.',posts:[{by:'analogkid',time:'14/04/2002, 14:34',txt:'A fita fica agarrando no final. Tem conserto? Eu preciso devolver amanhã.'},{by:'vhsfan',time:'14/04/2002, 16:08',txt:'Se travou, não puxa pela fita. E o botão costuma estar no painel do próprio aparelho.'}]},
{id:'0148',cat:'fenomenos',title:'Alguém gravou a transmissão da madrugada?',author:'radiohead99',date:'03/08/2003, 05:11',replies:17,desc:'Discussão sobre rádios locais.',posts:[{by:'radiohead99',time:'03/08/2003, 05:11',txt:'Meu rádio pegou uma voz num canal que não existe. Confiram 103.3. O locutor não disse o nome da estação.'},{by:'ghostwire',time:'03/08/2003, 09:40',txt:'Não abram mais cinco tópicos com o mesmo título. Já existe este.'}]},
{id:'0119',cat:'avisos',title:'[FIXO] Regras de convivência do fórum',author:'admin_000',date:'14/02/2002, 20:21',replies:4,desc:'Leia antes de postar.',posts:[{by:'admin_000',time:'14/02/2002, 20:21',txt:'1. Sem spam. 2. Não publique endereços pessoais. 3. Use títulos claros. 4. Trate os demais com respeito. 5. Nada de conteúdo que provoque mal-estar sem aviso.\n\nDúvidas podem ser enviadas por mensagem privada.'}]},
{id:'0213',cat:'musica',title:'As Misstapes estão procurando um baixista?',author:'cassettekid',date:'05/07/2003, 19:22',replies:19,desc:'Debates sobre banda de garagem.',posts:[{by:'cassettekid',time:'05/07/2003, 19:22',txt:'Ouvi uma fita das Misstapes, é sério que eles têm duas guitarras e um vocalista que grita no microfone de karaokê?\n\nA capa do demo é um desastre. Quero uma.'},{by:'quietboy',time:'05/07/2003, 20:01',txt:'o guitarrista não dá entrevista. isso é normal.'},{by:'analogkid',time:'06/07/2003, 11:11',txt:'Achei o site deles em um webring. O contador de visitas tá parado em 000013.'}]},
{id:'0008',cat:'avisos',title:'Quem ainda usa Internet discada?',author:'badsector',date:'02/03/2003, 18:23',replies:21,desc:'Discussão cotidiana.',posts:[{by:'badsector',time:'02/03/2003, 18:23',txt:'Se alguém souber como não cair a conexão quando a minha mãe tira o telefone do gancho, eu agradeço.'},{by:'analogkid',time:'02/03/2003, 20:02',txt:'Não tem como vencer uma mãe e um modem. Já tentei.'}]},
{id:'0156',cat:'musica',title:'Top 5 piores filmes de terror de locadora',author:'vhsfan',date:'29/07/2003, 21:05',replies:32,desc:'Listas e recomendações de filmes ruins.',posts:[{by:'vhsfan',time:'29/07/2003, 21:05',txt:'Pior do que um filme ruim é pagar multa pra devolver. Aceito indicações horríveis.'},{by:'mestre_antigo',time:'29/07/2003, 21:32',txt:'Minha regra: quanto mais bonita a capa, pior o filme.'}]},
{id:'9914',cat:'ocultos',title:'Log 14: conta sem histórico',author:'admin_000',date:'[sem data]',replies:'?',desc:'Material que não deveria constar no índice.',posts:[{by:'admin_000',time:'[não disponível]',txt:'RESUMO DE MODERAÇÃO\n\nO índice informa 13 conexões. O contador de perfis informa 14. A diferença persiste após a restauração de três backups.\n\nNão tratar o registro excedente como membro. Não apagar o índice novamente. A ausência parece contaminar a listagem.'},{by:'_',time:'[registro parcial]',txt:'não foi a conta que entrou. foi o nome que saiu.'}]}
];
const logList=[['count','O décimo quarto nome','Conferir a diferença no contador de usuários.'],['empty','Perfil vazio','Visitar a conta sem identificação.'],['signature','Mensagem na assinatura','Encontrar a referência oculta no perfil.'],['zip','O anexo da locadora','Recuperar o arquivo protegido por senha.'],['cache','Uma versão anterior','Consultar o cache da postagem apagada.'],['radio','Frequência 103.3','Sintonizar a transmissão estranha.'],['restored','Recuperação parcial','Concluir uma restauração no arquivo danificado.'],['secret','Arquivo da moderação','Abrir os registros não indexados.'],['band','Fita das Misstapes','Descobrir uma surpresa no site da banda.']];
let current={page:'home'}, selectedBook=1, selectedYear='2003', selectedSite='locadora', radioFreq=98.7, radioPlaying=false, audioContext=null, audioNodes=[], restoreValue=0, openedOS='', searchQuery='', visitCategory='all';
const mark=(id,message)=>{if(!state.found[id]){state.found[id]=true;save();toast('REGISTRO RECUPERADO',message||'Uma nova descoberta foi adicionada ao caderno.');renderRight();}else save();};
function toast(title,msg){const root=qs('#toast-root');root.innerHTML=`<div class="toast"><strong>${esc(title)}</strong><div style="margin-top:5px">${esc(msg)}</div></div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>root.innerHTML='',4600);}
function modal(title,body){qs('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="os-title"><span>▣ ${esc(title)}</span><button data-act="close-modal" style="color:#fff;background:#923f42;border:1px solid #c99;padding:0 6px" aria-label="Fechar">×</button></div><div class="modal-body">${body}</div></div></div>`;}
function goto(page,arg){if(radioPlaying&&page!=='radio')stopRadioSound();current={page,arg};location.hash='#'+page+(arg?'/'+encodeURIComponent(arg):'');render();qs('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:state.settings.motion?'smooth':'instant'});}
function syncHash(){let h;try{h=decodeURIComponent(location.hash.slice(1)||'home')}catch(e){h='home';}const [page,...args]=h.split('/');const allowed=['home','forum','category','thread','profile','library','captures','radio','desktop','sites','guestbook','proxy','notebook','settings','search','admin','inbox'];current={page:allowed.includes(page)?page:'home',arg:args.join('/')};render();}
function headerTitle(t,meta=''){return `<div class="section-head"><span>${t}</span>${meta?`<span class="sub">${meta}</span>`:''}</div>`;}
function dataButton(label,act,arg='',cls='btn'){return `<button class="${cls}" data-act="${act}" data-arg="${esc(arg)}">${label}</button>`;}
function navButton(id,label){return `<button data-go="${id}" class="${current.page===id?'active':''}">${label}</button>`;}
function renderNav(){qs('#navbar').innerHTML=navItems.map(([id,label])=>navButton(id,label)).join('');document.body.classList.toggle('motion-off',!state.settings.motion);}
function renderSide(){qs('#leftbar').innerHTML=`<div class="pane"><div class="pane-title">MENU PRINCIPAL</div><div class="pane-body">${[['home','▣ Página inicial'],['forum','▤ Fóruns e tópicos'],['library','▣ Biblioteca CHIADO'],['captures','◷ Capturas do site'],['sites','▥ Sites associados'],['guestbook','✎ Livro de visitas'],['notebook','▧ Caderno de descobertas'],['settings','⚙ Preferências']].map(([p,t])=>`<button class="side-link ${current.page===p?'on':''}" data-go="${p}">${t}</button>`).join('')}</div></div><div class="pane"><div class="pane-title">SISTEMAS</div><div class="pane-body"><button class="side-link" data-go="radio">♫ Receptor de rádio</button><button class="side-link" data-go="desktop">▣ Área de trabalho</button><button class="side-link" data-go="proxy">✎ Cadastro de Proxy</button><button class="side-link" data-go="admin">▤ Área administrativa</button><button class="side-link" data-go="inbox">✉ Mensagens privadas <b>[1]</b></button></div></div><div class="pane"><div class="pane-title">BUSCAR NO ARQUIVO</div><div class="pane-body"><form id="side-search"><label for="search-term" class="tiny">Pesquisar tópicos, usuários e capítulos</label><input id="search-term" class="field" placeholder="Pesquisar..." value="${esc(searchQuery)}"><button class="btn" style="width:100%;margin-top:7px" type="submit">Pesquisar »</button></form></div></div>`;}
function renderRight(){qs('#rightbar').innerHTML=`<div class="pane"><div class="pane-title">QUEM ESTÁ ONLINE?</div><div class="pane-body"><div class="stat-line"><span>Usuários online</span><strong>13</strong></div><div class="tiny" style="margin-top:7px">${members.map(m=>`<button data-go="profile" data-arg="${esc(m.u)}" class="click-link" style="font-size:10px">${esc(m.u)}</button>`).join(' · ')}</div><div style="margin-top:8px">${dataButton('Lista de membros »','members','','btn')}</div></div></div><div class="pane"><div class="pane-title">STATUS DO SERVIDOR</div><div class="pane-body"><div class="stat-line"><span>Estado</span><b><span class="status-led"></span>ONLINE</b></div><div class="stat-line"><span>Último backup</span><span>18/06/2003</span></div><div class="stat-line"><span>Versão</span><span>2.03-beta</span></div><div class="stat-line"><span>Capturas</span><span>4</span></div><div class="stat-line"><span>Registros recuperados</span><span>${Object.keys(state.found).length}/${logList.length}</span></div></div></div><div class="pane"><div class="pane-title">CAIXA DE ENTRADA</div><div class="pane-body"><div class="right-card"><h4>✉ Mensagem não lida</h4><div class="tiny">De: sistema_bbs · 03:33</div><p style="font-size:11px;margin:6px 0">Há diferenças entre as cópias.</p><button class="click-link" data-go="inbox">Abrir mensagem »</button></div></div></div>`;}
function render(){renderNav();renderSide();renderRight();const names={home:'Página inicial',forum:'Fórum',category:'Fóruns',thread:'Tópico',profile:'Perfil',library:'Livro do Proxy',captures:'Capturas',radio:'Receptor de rádio',desktop:'Área de trabalho',sites:'Sites associados',guestbook:'Livro de visitas',proxy:'Cadastro de Proxy',notebook:'Descobertas',settings:'Preferências',search:'Resultados da busca',admin:'Área administrativa',inbox:'Mensagens privadas'};qs('#breadcrumb-current').textContent=names[current.page]||'Arquivo';const handlers={home:pageHome,forum:pageForum,category:pageCategory,thread:pageThread,profile:pageProfile,library:pageLibrary,captures:pageCaptures,radio:pageRadio,desktop:pageDesktop,sites:pageSites,guestbook:pageGuestbook,proxy:pageProxy,notebook:pageNotebook,settings:pageSettings,search:pageSearch,admin:pageAdmin,inbox:pageInbox};qs('#main').innerHTML=(handlers[current.page]||pageHome)(current.arg);if(current.page==='library')loadBook();if(current.page==='profile'&&current.arg==='_')mark('empty','Um perfil sem histórico foi localizado.');}
function pageHome(){return `${headerTitle('BEM-VINDO AO ARQUIVO MORTO','Comunidade de assuntos estranhos • est. 1999')}<div class="content-panel"><p class="intro-lead"><strong>Olá, visitante.</strong> Este fórum reúne pessoas interessadas em fitas, fenômenos incomuns, rádios, relatos e coisas que ninguém mais parece lembrar. Leia as regras, seja gentil e evite publicar informações pessoais.</p><div class="notice dark">▣ <b>Atualização:</b> as capturas antigas estão disponíveis no menu Arquivos. Alguns anexos podem exigir programas antigos.</div><div class="kpi-grid"><div class="kpi"><strong>1.203</strong><small>mensagens</small></div><div class="kpi"><strong>317</strong><small>tópicos arquivados</small></div><div class="kpi"><strong>13</strong><small>usuários online</small></div></div><p class="info-footer">Dica: nomes, datas e referências entre tópicos são clicáveis. Nem todas as páginas estão indexadas.</p></div>${headerTitle('CENTRAL DE DISCUSSÕES','Clique para explorar uma categoria')}<div class="post-list">${cats.filter(c=>!c.secret||state.found.secret).map(catRow).join('')}</div><div class="homepage-grid" style="margin-top:15px"><div>${headerTitle('TÓPICOS RECENTES')}${topics.filter(t=>t.cat!=='ocultos'&&t.id!=='0042').slice(0,5).map(topicCompact).join('')}</div><div>${headerTitle('AVISOS DO FÓRUM')}<div class="content-panel"><b>► Sobre o Arquivo Morto</b><p>O site nasceu como uma troca de histórias, equipamentos e arquivos. Após sucessivas falhas no servidor, cópias foram preservadas por usuários.</p><p>Visite o <button class="click-link" data-go="captures">arquivo de capturas</button> e a <button class="click-link" data-go="library">biblioteca do CHIADO</button>.</p><div class="notice">Aviso de manutenção, 2003: a lista de membros pode apresentar inconsistências. Não envie novos cadastros por enquanto.</div>${dataButton('Ler as regras do fórum','thread','0119')}</div></div></div>`;}
function catRow(c){return `<div class="forum-row" data-go="category" data-arg="${esc(c.id)}" tabindex="0" role="link"><span class="category-icon">${c.icon}</span><div><strong>${esc(c.name)}</strong><div class="desc">${esc(c.desc)}</div></div><div class="count">${c.count}<div class="tiny">tópicos</div></div></div>`;}
function topicCompact(t){return `<div class="forum-row" data-go="thread" data-arg="${t.id}" tabindex="0" role="link" style="grid-template-columns:21px minmax(0,1fr)"><span class="category-icon" style="font-size:17px">▤</span><div><strong>${esc(t.title)}</strong><div class="desc">por ${esc(t.author)} · ${esc(t.date)}</div></div></div>`;}
function pageForum(){return `${headerTitle('FÓRUM ARQUIVO MORTO','Índice de categorias')}<div class="post-list">${cats.filter(c=>!c.secret||state.found.secret).map(catRow).join('')}</div><div class="notice">Última atualização do índice: 18/06/2003, 03:33. Algumas contagens podem estar desatualizadas.</div><div class="btn-row">${dataButton('Ver todos os membros','members')}${dataButton('Pesquisar postagens','search')}</div>`;}
function pageCategory(id){const cat=cats.find(c=>c.id===id)||cats[0];if(cat.secret&&!state.found.secret)return headerTitle('ACESSO NEGADO')+'<div class="content-panel">Esta categoria não está indexada.</div>';return `${headerTitle(esc(cat.name),esc(cat.desc))}<div class="post-list">${topics.filter(t=>t.cat===cat.id&&t.id!=='0042').map(topicCompact).join('')}</div><div class="btn-row">${dataButton('« Voltar ao índice','go','forum')}</div>`;}
function postText(raw){return esc(raw).replace(/\n/g,'<br>');}
function showPost(post,i){const m=members.find(x=>x.u===post.by)||members[0];return `<div class="topic"><div class="topic-head">Postagem #${i+1} — ${esc(post.time)}</div><div class="topic-body"><div class="topic-author"><div class="avatar ${m.u==='_'?'ghost':''}">${esc(m.avatar)}</div><button data-go="profile" data-arg="${esc(post.by)}" class="click-link" style="font-weight:bold">${esc(post.by)}</button><div class="tiny">${esc(m.tag)}</div><div class="tiny">Mensagens: ${esc(m.posts)}</div></div><div class="topic-text">${postText(post.txt)}${post.attach?`<div style="margin:13px 0"><button class="btn" data-act="open-zip">▣ ${esc(post.attach)} <span class="tiny">12 KB · ZIP</span></button></div>`:''}<div class="topic-sign">${esc(m.sign||'[sem assinatura]')}</div></div></div></div>`;}
function pageThread(id){const topic=topics.find(x=>x.id===id);if(!topic)return `${headerTitle('TÓPICO NÃO ENCONTRADO')}<div class="content-panel">Nenhum registro disponível.</div>`;if(topic.cat==='ocultos'&&!state.found.secret)return `${headerTitle('PERMISSÃO NEGADA')}<div class="content-panel">Você não possui acesso à categoria.</div>`;if(id==='0042')mark('found42','Você localizou uma publicação sem conteúdo, mas com um cache preservado.');let extra='';if(id==='0042')extra=`<div class="notice red"><b>Este tópico foi removido.</b> Uma cópia anterior ainda está disponível.<div class="btn-row">${dataButton('Abrir versão em cache (2001)','cache')}${dataButton('Ver todas as capturas','go','captures')}</div></div>`;if(id==='0213')extra=`<div class="notice dark">Uma banda amadora listada no <button class="click-link" data-go="sites" data-arg="misstapes">webring</button> apareceu nas respostas. Talvez ainda exista um site.</div>`;const saved=state.bookmarks.includes('thread:'+id);return `${headerTitle('TÓPICO #'+id+' · '+esc(topic.title),esc(topic.date))}<div class="topic-bar"><div class="tiny">Fórum: <button class="click-link" data-go="category" data-arg="${topic.cat}">${esc(cats.find(c=>c.id===topic.cat)?.name||'Arquivos')}</button></div><div class="buttons-right">${dataButton(saved?'★ Salvo':'☆ Salvar tópico','bookmark','thread:'+id)}${dataButton('Voltar','go','forum')}</div></div>${extra}${topic.posts.map(showPost).join('')}<div class="notice dark">▣ Este arquivo é uma reprodução de uma discussão fictícia, não um fórum público ativo.</div>`;}
function pageProfile(u){if(u==='all'){return `${headerTitle('LISTA DE MEMBROS','13 usuários online')}${memberList()}`;}const m=members.find(x=>x.u===u)||members[0];if(u==='_')return `${headerTitle('PERFIL DE USUÁRIO','REGISTRO INCOMPLETO')}<div class="content-panel"><div class="profile-hero"><div class="avatar ghost" style="font-size:46px">&nbsp;</div><div><h2 style="margin:0;color:#5e7380">_</h2><div class="tiny">Cargo: [não atribuído]</div><div class="tiny">Registrado: [campo em branco]</div><div class="tiny">Última atividade: [sem dados]</div></div></div><p>Não há postagens públicas vinculadas a esta conta.</p><div class="archive-prompt">Assinatura do usuário:<div class="topic-sign" style="background:#f8fbfc;padding:14px" title="Talvez valha selecionar a área vazia"><span id="secret-signature" class="signature-hidden">REF: #0042 · capture://2001</span></div></div><div class="btn-row">${dataButton('Selecionar / revelar assinatura','signature')}${dataButton('Buscar este usuário','search-user','_')}</div><p class="info-footer">Este registro foi reconstruído a partir de campos vazios do índice.</p></div>`;return `${headerTitle('PERFIL DE USUÁRIO',esc(m.u))}<div class="content-panel"><div class="profile-hero"><div class="avatar">${esc(m.avatar)}</div><div><h2 style="margin:0;color:#355d79">${esc(m.u)}</h2><div class="tiny">${esc(m.tag)}</div><div class="tiny">Registrado: ${esc(m.since)}</div><div class="tiny">Postagens: ${esc(m.posts)}</div></div></div><div class="archive-prompt">Assinatura:<p>${esc(m.sign||'[sem assinatura]')}</p></div><h3>Publicações</h3>${topics.filter(t=>t.posts.some(p=>p.by===m.u)).slice(0,7).map(topicCompact).join('')||'<p class="muted">Nenhuma postagem indexada.</p>'}</div>`;}
function memberList(){return `<div class="content-panel"><div class="member-list">${members.map(m=>`<div class="member-item" data-go="profile" data-arg="${esc(m.u)}" tabindex="0" role="link"><div class="avatar ${m.u==='_'?'ghost':''}">${esc(m.avatar)}</div><div><b>${esc(m.u)}</b><small>${esc(m.tag)}</small><small>${esc(m.posts)} postagens</small></div></div>`).join('')}</div></div>`;}
function pageLibrary(){return `${headerTitle('BIBLIOTECA CHIADO :: LIVRO DO PROXY','Arquivos catalogados')}
<div class="content-panel"><p class="intro-lead">Os volumes do <b>Livro do Proxy</b> estão catalogados para consulta. Todos os registros disponíveis podem ser lidos sem autorização especial.</p><div class="notice dark">► Há <b>seis arquivos numerados</b> disponíveis, além das páginas preliminares. O Arquivo 07 é anunciado no sumário, mas não consta no documento-fonte e não foi inventado.</div><div class="tabs">${chapters.map(c=>`<button data-act="book-select" data-arg="${c.n}" class="${selectedBook===c.n?'active':''}">${c.n===0?'Prelim.':'Arquivo '+String(c.n).padStart(2,'0')}</button>`).join('')}</div><div class="chreader-layout"><aside id="book-toc" class="chreader-nav"></aside><article id="book-content" class="manual-reader" aria-label="Capítulo do Livro do Proxy"></article></div><div class="btn-row">${dataButton('◉ Modo de leitura externo','full-book')}${dataButton('Salvar este capítulo','bookmark','book:'+selectedBook)}</div><p class="tiny">A apresentação do texto dentro do arquivo usa estilos de leitura; a versão completa e original está incluída separadamente no pacote do site.</p></div>`;}
function loadBook(){let t=qs('#book-'+selectedBook), output=qs('#book-content');if(!t||!output)return;output.innerHTML=t.innerHTML;const headings=[...output.querySelectorAll('h2')];headings.forEach((h,i)=>h.id='subsec-'+i);const b=chapters.find(c=>c.n===selectedBook);qs('#book-toc').innerHTML=`<div class="label">${esc(b.t)}</div><p class="tiny">${esc(b.desc)}</p>${headings.map((h,i)=>`<button data-act="book-jump" data-arg="${i}">${esc(h.textContent.trim())}</button>`).join('')||'<p class="tiny">Capa, créditos e segurança.</p>'}`;output.scrollTop=0;}
function pageCaptures(){const data={'1999':{title:'O começo',text:'Página inicial construída em HTML simples. Onze links quebrados, uma lista de e-mails e um livro de visitas. Nenhum fenômeno registrado.',extra:'O administrador assinava apenas como A.M.'},'2001':{title:'O primeiro espelho',text:'Cópia anterior à migração para o novo servidor. Um tópico removido aparece parcialmente no índice.',extra:'O tópico #0042 apresenta data incompatível com seu registro atual.'},'2003':{title:'A comunidade em funcionamento',text:'O fórum alcança seu maior número de participantes ativos. A lista de membros passou a exibir divergências.',extra:'O contador informa 13 usuários. A lista, porém, não confere.'},'2005':{title:'Desativação do servidor',text:'O administrador anuncia o encerramento das postagens. O serviço de leitura permanece temporariamente no ar.',extra:'Uma última manutenção aparece nos logs após o suposto desligamento.'}};let d=data[selectedYear];return `${headerTitle('CAPTURAS DO ARQUIVO MORTO','Cópias arquivadas do servidor 1999—2005')}<div class="content-panel"><p>Selecione uma data para consultar uma versão anterior. As páginas são reproduções ficcionais de backups incompletos.</p><div class="time-select">${Object.keys(data).map(y=>`<button class="${selectedYear===y?'selected':''}" data-act="year" data-arg="${y}">${y}</button>`).join('')}</div><div class="archive-card" style="margin-top:14px"><h2 style="color:#485b59;margin:6px 0">${esc(selectedYear)} :: ${esc(d.title)}</h2><p>${esc(d.text)}</p><div class="diary">${esc(d.extra)}</div><div class="tiny">HASH: AM-${selectedYear}-BACKUP · INTEGRIDADE: ${selectedYear==='2001'?'68%':'PARCIAL'}</div>${selectedYear==='2001'?`<div class="btn-row">${dataButton('Abrir cache do tópico #0042','cache')}${dataButton('Ver tópico atual #0042','thread','0042')}</div>`:''}${selectedYear==='2003'?`<div class="btn-row">${dataButton('Ver lista de membros','members')}${dataButton('Conferir estatísticas','count')}</div>`:''}</div></div>${headerTitle('HISTÓRICO DE RESTAURAÇÃO')}<div class="content-panel"><div class="timeline"><div class="timeline-item"><h3>1999 — Registro inicial</h3><div class="tiny">Uma comunidade sobre mídia analógica aparece nos diretórios.</div></div><div class="timeline-item"><h3>2001 — Cópia de emergência</h3><div class="tiny">Arquivos são preservados antes de uma migração de servidor.</div></div><div class="timeline-item"><h3>2003 — Inconsistências de índice</h3><div class="tiny">A moderação suspende o cadastro de novos membros.</div></div><div class="timeline-item"><h3>2005 — Fechamento</h3><div class="tiny">Os registros de atividade cessam. Nem todas as alterações cessam com eles.</div></div></div></div>`;}
function pageRadio(){const station=getStation();return `${headerTitle('SINTONIZADOR DE FREQUÊNCIAS','AM-RADIO v2.4 • receptor de ondas curtas')}<div class="content-panel"><div class="radio-frame"><div style="display:flex;justify-content:space-between;color:#cbd9cc"><b>▤ RECEPTOR ANALÓGICO</b><span class="mono">AM-07</span></div><div class="lcd" id="radio-frequency">${radioFreq.toFixed(1)} MHz</div><p id="radio-name" style="text-align:center;color:#deeede;font-weight:bold">${esc(station.name)}</p><input id="radio-slider" aria-label="Frequência de rádio" type="range" min="88" max="104" step="0.1" value="${radioFreq}"><div style="display:flex;justify-content:space-between"><small>88.0 MHz</small><small>104.0 MHz</small></div><div class="btn-row"><button class="btn" data-act="radio-audio">${radioPlaying?'■ Desligar áudio':'▶ Ligar áudio ambiente'}</button><button class="btn" data-act="radio-step" data-arg="-0.1">◀</button><button class="btn" data-act="radio-step" data-arg="0.1">▶</button></div><div class="terminal" style="margin-top:12px"><div id="radio-transcript">${esc(station.transcript)}</div></div></div><p class="info-footer">O áudio é gerado localmente, em volume baixo, apenas após clicar em “Ligar”. O mistério é totalmente acessível sem som.</p><div class="notice dark">O rádio também funciona como referência para os materiais de campanha. Procure as frequências mencionadas nas postagens.</div></div>`;}
function getStation(){const stations=[{f:88.3,name:'Rádio Aurora 88.3',transcript:'Música instrumental e notícias da cidade. Sem ocorrências.'},{f:94.1,name:'Vozes da Cidade 94.1',transcript:'Boletim das 20h: trânsito lento na avenida central. Um ouvinte pede música.'},{f:98.7,name:'Rádio Comunitária 98.7',transcript:'“Boa noite, ouvintes. A programação continua após este intervalo.”'},{f:103.3,name:'[ ESTAÇÃO NÃO IDENTIFICADA ]',transcript:'[TRANSCRIÇÃO, 03:33] O contador não está quebrado. Há um nome a mais. A lista não está errada.'}];const s=stations.find(x=>Math.abs(x.f-radioFreq)<.045);return s||{name:'--- SINAL NÃO IDENTIFICADO ---',transcript:'Ruído de fundo. Nenhuma estação identificada.'};}
function radioUpdate(){const s=getStation();if(qs('#radio-frequency'))qs('#radio-frequency').textContent=radioFreq.toFixed(1)+' MHz';if(qs('#radio-name'))qs('#radio-name').textContent=s.name;if(qs('#radio-transcript'))qs('#radio-transcript').textContent=s.transcript;if(Math.abs(radioFreq-103.3)<.045)mark('radio','Você encontrou uma transmissão que comenta a lista de usuários.');}
function startRadioSound(){try{const ctx=new(window.AudioContext||window.webkitAudioContext)();audioContext=ctx;const length=ctx.sampleRate*2,b=ctx.createBuffer(1,length,ctx.sampleRate),data=b.getChannelData(0);for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*.13;const src=ctx.createBufferSource();src.buffer=b;src.loop=true;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=850;const gain=ctx.createGain();gain.gain.value=.08;src.connect(filter);filter.connect(gain);gain.connect(ctx.destination);src.start();audioNodes=[src,gain];radioPlaying=true;toast('RECEPTOR LIGADO','Áudio ambiente discreto ativado.');}catch(e){toast('ÁUDIO INDISPONÍVEL','O navegador não permitiu iniciar o áudio. A transcrição continua disponível.');}}
function stopRadioSound(){try{audioNodes[0]?.stop();audioContext?.close();}catch(e){}audioNodes=[];audioContext=null;radioPlaying=false;}
function pageDesktop(){return `${headerTitle('ESTAÇÃO DE TRABALHO — AM-OS 2000','Terminal de recuperação • modo local')}<div class="content-panel"><p>Terminal de recuperação AM-OS. Selecione um atalho para examinar documentos, anexos e registros disponíveis.</p><div class="desktop-bg" id="desktop-canvas"><div class="os-icons">${[['▤','REGISTRO.TXT','notepad'],['▣','Restauração','restore'],['▥','LOCA07.ZIP','zip'],['♫','TAPE_PLAYER','tape'],['▧','Lixeira','trash'],['▦','ADMIN.SYS','admin']].map(x=>`<button class="os-shortcut" style="color:#eff8f7" data-act="os-open" data-arg="${x[2]}"><span>${x[0]}</span><span>${x[1]}</span></button>`).join('')}</div><div id="os-app" class="os-window" style="position:absolute;left:33%;top:66px;width:60%;min-height:100px;margin:0;z-index:2"><div class="os-title">▣ Ajuda do sistema <span>□ ×</span></div><div class="os-main">Clique em um ícone para abrir um programa fictício. Arraste esta janela pela barra azul.</div></div></div></div>`;}
function renderOS(which){openedOS=which;let inner='';if(which==='notepad')inner=`<div class="mono" style="background:#fff;padding:17px;border:1px solid #9daab1;white-space:pre-line">ARQUIVO MORTO — MEMORANDO INTERNO\n\nEm caso de inconsistência na contagem de usuários, consultar as capturas anteriores.\n\nSe o problema persistir, não tente remover manualmente o registro.</div>${dataButton('Abrir capturas','go','captures')}`;
else if(which==='restore')inner=`<p>Selecione a intensidade de recuperação do registro.</p><div class="terminal"><div id="restore-readout">${restoreText(restoreValue)}</div></div><label class="field-label" for="restore-slider">Reconstrução: <span id="restore-number">${restoreValue}%</span></label><input type="range" min="0" max="100" value="${restoreValue}" step="5" id="restore-slider" style="width:100%"><div class="btn-row">${dataButton('Reiniciar recuperação','restore-reset')}${dataButton('Salvar arquivo recuperado','restore-save')}</div>`;
else if(which==='zip')inner=`<p>LOCA07.ZIP — Arquivo protegido</p>${dataButton('Abrir extrator de arquivos','open-zip')}`;
else if(which==='tape')inner=`<p><b>TAPE_PLAYER 1.0</b></p><p>Fita inserida: <span class="mono">MISSTAPES_DEMO.K7</span></p>${dataButton('Abrir site das Misstapes','site','misstapes')}`;
else if(which==='trash')inner=`<p>“A lixeira está vazia.”</p><p class="tiny">Última limpeza: 18/06/2003, 03:33</p>`;
else if(which==='admin')inner=`<p>O acesso exige identificação de arquivo.</p>${dataButton('Abrir área administrativa','go','admin')}`;
if(qs('#os-app'))qs('#os-app').innerHTML=`<div class="os-title">▣ ${esc(which.toUpperCase())} <span>□ ×</span></div><div class="os-main">${inner}</div>`;}
function restoreText(v){if(v<25)return 'ARQUIVO: ▒▒▒▒/0033\nREMETENTE: ██████\nSTATUS: CORROMPIDO';if(v<60)return 'ARQUIVO: FÓRUM / 0033\nREMETENTE: [REMOVIDO]\n...O ÍNDICE NÃO...';if(v<85)return 'ARQUIVO: CÓPIA DE MODERAÇÃO\nREMETENTE: ADMIN_000\nCONTA A MAIS. NÃO APAGAR.';return 'ARQUIVO: CÓPIA DE MODERAÇÃO\nREMETENTE: ADMIN_000\nDESTINO: TÓPICO #0042\nO NOME ESTÁ AUSENTE, MAS O ESPAÇO CONTINUA.';}
const microsites=[{id:'locadora',name:'Locadora Central',desc:'Catálogo e devoluções de VHS'},{id:'radio98',name:'Radio 98.7 FM',desc:'Emissora comunitária'},{id:'misstapes',name:'Misstapes Official',desc:'Site da banda amadora'},{id:'silentroom',name:'SilentRoom',desc:'Página pessoal abandonada'},{id:'hospital',name:'Hospital Santa Cecília',desc:'Página institucional antiga'}];
